out = os.path.join(os.path.dirname(__file__), "..", "app", "lib", "l10n")
os.makedirs(out, exist_ok=True)
for i, lang in enumerate(LANGS):
    d = {"@@locale": lang}
    for k, v in T.items():
        assert len(v) == 7, k
        d[k] = v[i]
    for k, v in P.items():
        ph, typ = v[0], v[1]
        d[k] = v[2 + i]
        if i == 0:
            d["@" + k] = {"placeholders": {ph: {"type": typ}}}
    with open(os.path.join(out, f"app_{lang}.arb"), "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=1)
print("生成完成：", len(T) + len(P), "条 ×", len(LANGS), "种语言")
